def gen(rng):
    CAP = 4999

    def make_tree(n, mode):
        par = [-1] * n
        depth = [0] * n
        okn = [0]  # nodes with depth < CAP
        for i in range(1, n):
            if mode == 'rand':
                p = rng.randrange(i)
            elif mode == 'path':
                p = i - 1
            elif mode == 'near':
                p = rng.randrange(max(0, i - 3), i)
            else:  # star-ish
                p = rng.randrange(min(i, 3))
            if depth[p] >= CAP:
                p = rng.choice(okn)
            par[i] = p
            depth[i] = depth[p] + 1
            if depth[i] < CAP:
                okn.append(i)
        return par

    def fmt(par, vals, m):
        n = len(par)
        perm = list(range(1, n))
        rng.shuffle(perm)
        lab = [0] + perm
        edges = []
        for i in range(1, n):
            a, b = lab[par[i]], lab[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        v2 = [0] * n
        for i in range(n):
            v2[lab[i]] = vals[i]
        return f'{n} {m}\n' + ' '.join(map(str, v2)) + ''.join(f'\n{a} {b}' for a, b in edges)

    def values(n, m, maxv, style):
        out = []
        for _ in range(n):
            if style == 0:
                out.append(rng.randint(0, maxv))
            elif style == 1:
                out.append(rng.choice([0, m, 2 * m, rng.randint(0, maxv)]) % (maxv + 1))
            else:
                out.append(rng.randint(0, min(maxv, 2 * m)))
        return out

    tests = [
        '1 1\n0',
        '1 5\n5',
        '1 5\n4',
        '3 1\n7 0 9\n0 1\n0 2',
        '4 4\n2 2 2 2\n0 1\n1 2\n2 3',
    ]
    for _ in range(40):
        n = rng.randint(1, 12)
        m = rng.choice([1, 2, 3, 4, 5, 7, 10])
        par = make_tree(n, rng.choice(['rand', 'path', 'near', 'star']))
        tests.append(fmt(par, values(n, m, rng.choice([10, 30]), rng.choice([0, 1, 2])), m))
    for n, mode, m, style in ((300, 'rand', 7, 0), (2000, 'near', 100, 1), (5000, 'path', 3, 2), (3000, 'star', 1, 0)):
        tests.append(fmt(make_tree(n, mode), values(n, m, 10**9, style), m))
    N = 10**5
    tests.append(fmt(make_tree(N, 'path'), values(N, 5, 10**9, 2), 5))
    tests.append(fmt(make_tree(N, 'near'), values(N, 100000, 10**9, 1), 100000))
    tests.append(fmt(make_tree(N, 'rand'), values(N, 1, 10**9, 0), 1))
    return tests

